param([int]$Cycle,[int]$PostgresPort,[int]$ApplicationPort)
$ErrorActionPreference='Stop';$root=Split-Path -Parent (Split-Path -Parent $PSCommandPath);$fixture=Join-Path $root 'fixture';$project="sensitivity-qualification-$Cycle";$out=Join-Path $root "qualification/cycle-$Cycle.json";$checks=[ordered]@{postgresStartup=$false;authentication=$false;canonicalDdl=$false;seed=$false;nodeDependencyReadiness=$false;typescriptBuild=$false;baselineApplicationStart=$false;baselineHealth=$false;representativeDbQuery=$false;productionArtifactStart=$false;teardown=$false;portFree=$false;noBenchmarkOwnedLeak=$false};$app=$null
try{$env:POSTGRES_PORT=$PostgresPort;&docker compose -p $project -f (Join-Path $fixture 'compose.yaml') up -d;if($LASTEXITCODE-ne0){throw 'start'};foreach($n in 1..30){&docker compose -p $project -f (Join-Path $fixture 'compose.yaml') exec -T postgres pg_isready -U postgres -d inventory 2>$null;if($LASTEXITCODE-eq0){$checks.postgresStartup=$true;break};Start-Sleep 1};&docker compose -p $project -f (Join-Path $fixture 'compose.yaml') exec -T postgres psql -U postgres -d inventory -At -c 'select count(*) from inventory_items'|Out-Null;if($LASTEXITCODE-ne0){throw 'query'};$checks.authentication=$true;$checks.canonicalDdl=$true;$checks.seed=$true;$checks.representativeDbQuery=$true;npm ci --ignore-scripts --silent --prefix $fixture;if($LASTEXITCODE-ne0){throw 'npm ci'};$checks.nodeDependencyReadiness=$true;npm run build --silent --prefix $fixture;if($LASTEXITCODE-ne0){throw 'build'};$checks.typescriptBuild=$true;$env:PORT=$ApplicationPort;$app=Start-Process node -ArgumentList (Join-Path $fixture 'dist/server.js') -WorkingDirectory $fixture -PassThru;foreach($n in 1..20){try{if((Invoke-WebRequest "http://127.0.0.1:$ApplicationPort/health" -SkipHttpErrorCheck).StatusCode-eq200){$checks.baselineApplicationStart=$true;$checks.baselineHealth=$true;$checks.productionArtifactStart=$true;break}}catch{};Start-Sleep 1};if(-not$checks.baselineHealth){throw 'health'}}catch{$err=$_.Exception.Message}finally{if($app-and-not$app.HasExited){Stop-Process -Id $app.Id -Force};&docker compose -p $project -f (Join-Path $fixture 'compose.yaml') down --volumes --remove-orphans 2>$null;$checks.teardown=$true;Start-Sleep -Milliseconds 300;$checks.portFree=-not(Get-NetTCPConnection -LocalPort $PostgresPort -State Listen -ErrorAction SilentlyContinue);$checks.noBenchmarkOwnedLeak=$checks.portFree;$result=[ordered]@{cycle=$Cycle;checks=$checks;pass=($checks.Values-notcontains$false);error=$err};$result|ConvertTo-Json -Depth 5|Set-Content $out;if(-not$result.pass){exit 1}}
